const base = 'https://n8n.example.com/webhook/empleo-hook';
const items = $input.all().map(i => i.json).slice(0, 12);
const ids = items.map(o => Number(o.id)).filter(Boolean);
const NL = String.fromCharCode(10);
const good = items.filter(o => (Number(o.score)||0) >= 80).length;
const mid = items.filter(o => { const s = Number(o.score)||0; return s >= 60 && s < 80; }).length;
const low = items.length - good - mid;
const dot = s => s >= 80 ? '🟢' : (s >= 60 ? '🟡' : '⚪');
let blocks = ['📋 Ofertas abiertas: ' + items.length + '   🟢 ' + good + ' · 🟡 ' + mid + ' · ⚪ ' + low, '━━━━━━━━━━━━━━'];
const keyboard = [];
items.forEach((o, idx) => {
  const n = idx + 1;
  const sc = Number(o.score) || 0;
  const kw = (o.keywords || '').toString().split(',').map(s => s.trim()).filter(Boolean).slice(0, 6).join(', ');
  const reason = (o.reasons || '').toString().replace(/\s+/g, ' ').trim().slice(0, 220);
  blocks.push('');
  blocks.push('#' + n + '  ' + dot(sc) + ' ' + sc + '/100 · ' + (o.verdict || ''));
  blocks.push('💼 ' + (o.title || 'Sin título') + ' — ' + (o.company || 'Empresa n/d'));
  const _loc0 = (o.location || '').trim();
  const _mod = (o.modalidad || '').trim();
  const _modish = s => /remot|teletrab|presencial|h[ií]brid|semipresencial|desde casa|anywhere/i.test(s);
  const _loc = (!_loc0 || _loc0.toLowerCase() === 'no indicada' || _modish(_loc0)) ? '' : _loc0;
  const _ubi = !_loc ? (_mod || 'ubicación n/d') : ((_mod && _loc.toLowerCase() !== _mod.toLowerCase()) ? (_loc + ' · ' + _mod) : _loc);
  blocks.push('📍 ' + _ubi);
  if (kw) blocks.push('🔑 ' + kw);
  if (reason) blocks.push('💡 ' + reason);
  blocks.push('🔗 ' + (o.url || ''));
  keyboard.push([
    { text: '📄 CV #' + n, url: base + '-generar?id=' + o.id },
    { text: '✅ Aplicar #' + n, url: base + '-aplicar?id=' + o.id },
    { text: '🗑️ #' + n, url: base + '-descartar?id=' + o.id }
  ]);
});
const text = blocks.join(NL).slice(0, 4000);
const reply_markup = { inline_keyboard: keyboard };
return [{ json: { text: text, reply_markup: reply_markup, ids: ids, count: items.length } }];

const ids = $('Construir digest').first().json.ids || [];
if (!ids.length) { return [{ json: { updateSql: 'SELECT 1;' } }]; }
const updateSql = `UPDATE empleo.job_offers SET status='notificada', notified_at=now(), updated_at=now() WHERE id IN (` + ids.join(',') + `) AND status='evaluada';`;
return [{ json: { updateSql: updateSql } }];

const raw = $json;
const asArr = v => { if (!v) return []; if (Array.isArray(v)) return v; try { return JSON.parse(v); } catch(e){ return []; } };
const est = asArr(raw.por_estado);
const top = asArr(raw.top_ofertas);
const pipe = asArr(raw.pipeline);
const NL = String.fromCharCode(10);
const c = v => String(v==null?'':v).split('|').join('/').split(NL).join(' ').trim();
const ubi = o => { const l=c(o.location); const m=c(o.modalidad); const isMod=/remot|teletrab|presencial|h.brid|semipresencial/i.test(l); const loc=(!l||l.toLowerCase()==='no indicada'||isMod)?'':l; return !loc?(m||'-'):(m&&loc.toLowerCase()!==m.toLowerCase()?loc+' - '+m:loc); };
const fecha = new Date().toISOString().slice(0,16).replace('T',' ');
const L = [];
L.push('---'); L.push('actualizado: ' + fecha); L.push('tags: [empleo, tablero]'); L.push('---');
L.push('# Tablero de busqueda de empleo'); L.push('');
L.push('Actualizado automaticamente por el radar. Ofertas nuevas ultimos 7 dias: ' + (raw.ultimas_7d||0) + '.'); L.push('');
L.push('## Estado general'); L.push('| Estado | Total |'); L.push('|---|---|');
for (const e of est) { L.push('| ' + c(e.status) + ' | ' + (e.c||0) + ' |'); }
L.push('');
L.push('## Oportunidades abiertas (' + top.length + ')'); L.push('| Score | Puesto | Empresa | Ubicacion | Tecnologias | Enlace |'); L.push('|---|---|---|---|---|---|');
for (const o of top) { L.push('| ' + (o.score||0) + ' | ' + c(o.title) + ' | ' + c(o.company) + ' | ' + ubi(o) + ' | ' + c(o.keywords).slice(0,60) + ' | [ver](' + c(o.url) + ') |'); }
L.push('');
L.push('## Detalle (top 15, todo lo que Telegram recorta)');
for (const o of top.slice(0,15)) { L.push(''); L.push('### ' + (o.score||0) + '/100 - ' + c(o.title) + ' (' + c(o.company) + ')'); L.push('- Ubicacion: ' + ubi(o)); if (c(o.keywords)) L.push('- Tecnologias: ' + c(o.keywords)); if (c(o.verdict)) L.push('- Veredicto: ' + c(o.verdict)); if (c(o.reasons)) L.push('- Encaje: ' + c(o.reasons)); L.push('- [Ver oferta](' + c(o.url) + ')'); }
L.push('');
L.push('## Candidaturas en curso');
if (!pipe.length) { L.push('Ninguna candidatura activa por ahora.'); }
else {
  L.push('| Empresa | Puesto | Fase | Aplicada | Proxima accion |'); L.push('|---|---|---|---|---|');
  for (const a of pipe) { L.push('| ' + c(a.company) + ' | ' + c(a.title) + ' | ' + c(a.stage) + ' | ' + (a.applied_at?String(a.applied_at).slice(0,10):'') + ' | ' + c(a.next_action) + (a.next_date?(' ('+String(a.next_date).slice(0,10)+')'):'') + ' |'); }
}
const md = L.join(NL);
const contentB64 = Buffer.from(md, 'utf8').toString('base64');
return [{ json: { path: '/vault/Ofertas/_TABLERO.md', contentB64: contentB64 } }];

const fs = require('fs');
fs.mkdirSync('/vault/Ofertas', { recursive: true });
fs.writeFileSync($json.path, Buffer.from($json.contentB64, 'base64'));
return [{ json: { ok: true, path: $json.path } }];

const raw = $json;
const asArr = v => { if (!v) return []; if (Array.isArray(v)) return v; try { return JSON.parse(v); } catch(e){ return []; } };
const rows = asArr(raw.rows);
const DQ = String.fromCharCode(34);
const NL10 = String.fromCharCode(10);
const NL13 = String.fromCharCode(13);
const estadoLabel = { aplicada: '1-Postulada', generada: '2-CV generado', notificada: '3-Notificada', evaluada: '4-Abierta', descartada: '5-Descartada' };
const q = v => { let s = String(v==null?'':v).split(DQ).join(DQ+DQ).split(NL10).join(' ').split(NL13).join(' '); return (s.indexOf(';')>=0 || s.indexOf(DQ)>=0) ? DQ+s+DQ : s; };
const cols = ['Estado','Empresa','Puesto','Ubicacion','Modalidad','Encaje','Veredicto','Fuente','Fecha_deteccion','Fecha_CV','Fecha_postulacion','URL'];
const out = [cols.join(';')];
for (const o of rows) { const est = estadoLabel[o.status] || String(o.status||''); out.push([est, o.company, o.title, o.location, o.modalidad, (o.score==null?'':o.score), o.verdict, o.source, o.fecha_deteccion, o.fecha_cv, o.fecha_postulacion, o.url].map(q).join(';')); }
const csv = String.fromCharCode(0xFEFF) + out.join(NL13+NL10);
const contentB64 = Buffer.from(csv, 'utf8').toString('base64');
return [{ json: { path: '/vault/Ofertas/candidaturas.csv', contentB64: contentB64 } }];

const fs = require('fs');
fs.mkdirSync('/vault/Ofertas', { recursive: true });
fs.writeFileSync($json.path, Buffer.from($json.contentB64, 'base64'));
return [{ json: { ok: true, path: $json.path } }];
